(Injectivity) Let $f,g\in C_\lambda$ and assume $\nu_\lambda(f)=\nu_\lambda(g)$,
namely
\begin{align*}
&e_sf\circ (d\circ (\pi_{(\lambda\times S,(i,t))})_{t\in S})_{i\in\lambda}
  \circ (e_t\circ \pi_{(\lambda\times S,(i,t))})_{(i,t)\in\lambda\times S}\\
=&e_sg\circ (d\circ (\pi_{(\lambda\times S,(i,t))})_{t\in S})_{i\in\lambda}
  \circ (e_t\circ \pi_{(\lambda\times S,(i,t))})_{(i,t)\in\lambda\times S}
\end{align*}
holds for all $s\in S$. Then
\begin{align*}
f
&=d\circ (e_sf)_{s\in S}\\
&=d\circ (e_sf)_{s\in S}\circ (\pi_{(\lambda,i)})_{i\in\lambda}\\
&=d\circ (e_sf)_{s\in S}\circ (d\circ (\pi_{(\lambda,i)})_{t\in S})_{i\in\lambda}\\
&=d\circ (e_sf)_{s\in S}\circ 
  (d\circ (\pi_{(\lambda\times S,(i,t))})_{t\in S})_{i\in\lambda}
  \circ (\pi_{(\lambda,i)})_{(i,t)\in\lambda\times S}\\
&=d\circ (e_sf)_{s\in S}\circ 
  (d\circ (e_t\pi_{(\lambda\times S,(i,t))})_{t\in S})_{i\in\lambda}
  \circ (\pi_{(\lambda,i)})_{(i,t)\in\lambda\times S}\\
&=d\circ (e_sf)_{s\in S}\circ 
  (d\circ (\pi_{(\lambda\times S,(i,t))})_{t\in S})_{i\in\lambda}
  \circ (e_t\pi_{(\lambda\times S,(i,t))})_{(i,t)\in\lambda}\circ (\pi_{(\lambda,i)})_{(i,t)\in\lambda\times S}\\
&=d\circ (e_sg)_{s\in S}\circ 
  (d\circ (\pi_{(\lambda\times S,(i,t))})_{t\in S})_{i\in\lambda}
  \circ (e_t\pi_{(\lambda\times S,(i,t))})_{(i,t)\in\lambda}\circ (\pi_{(\lambda,i)})_{(i,t)\in\lambda\times S}\\
&=g.
\end{align*}
Thus, $\nu_\lambda$ is injective.

(Surjectivity)
Suppose $f\in {\rm H}(C_d)$.
By definition of ${\rm H}(C_d)$, $f$ is described as
$f=(f_s/\mc\sim)_{s\in S}$ where $f_s\in C_{\lambda\times S}$
and each $f_s$ satisfies $e_sf_s=f_s$.



Let us define
\[
\tilde{f}:=d\circ (f_s)_{s\in S}
\circ(e_t\pi_{(\lambda,i)})_{(i,t)\in\lambda\times S}.
\]
Then $\nu_\lambda(\tilde{f})$ is calculated as follows:
\begin{align*}
\nu_\lambda(\tilde{f})
&= \left(e_s\tilde{f} \circ
 (d\circ (\pi_{(\lambda\times S,(i,u))})_{u\in S})_{i\in\lambda}/\sim\right)_{s\in S}\\
&=\left(e_s d\circ (f_{s'})_{s'\in S}
\circ(e_t\pi_{(\lambda,i)})_{(i,t)\in\lambda\times S}
\circ (d\circ (\pi_{(\lambda\times S,(i,u))})_{u\in S})_{i\in\lambda}/\mc\sim\right)_{s\in S}\\



&=\left(f_{s}
\circ (e_t\circ \pi_{(\lambda,i)})_{(i,t)\in\lambda\times S}
\circ (d\circ (\pi_{(\lambda\times S,(i,u))})_{u\in S})_{i\in\lambda}/\mc\sim\right)_{s\in S}\\
&=\left(f_{s}
\circ (e_td\circ (\pi_{(\lambda\times S,(i,u))})_{u\in S})_{(i,t)\in\lambda\times S}/\sim\right)_{s\in S}\\
&=\left(f_{s}
\circ (e_t\pi_{(\lambda\times S,(i,t))})_{(i,t)\in\lambda\times S}/\mc\sim\right)_{s\in S}\\
&=(f_{s}/\mc\sim)_{s\in S}\\
&=f.
\end{align*}

(Compatibility)
Let $f\in C_{\lambda_1}$, $g_i\in C_{\lambda_2}$ ($i\in \lambda_1$).
Then 
\begin{align*}
&\nu_{\lambda_2}(f\circ (g_i)_{i\in\lambda_1})\\
=&\left(e_s f\circ(g_i)_{i\in\lambda_1}
  \circ(d\circ(\pi_{(\lambda_2\times S,(j,t))})_{t\in S})_{j\in\lambda_2}/\mc\sim\right)_{s\in S}\\
=&\left(e_s f
  \circ (d\circ(e_u\circ \pi_{(\lambda_1,i)})_{u\in S})_{i\in\lambda_1}
  \circ(g_i)_{i\in\lambda_1}
  \circ(d\circ(\pi_{(\lambda_2\times S,(j,t))})_{t\in S})_{j\in\lambda_2}/\mc\sim\right)_{s\in S}\\
=&\left(e_s f
  \circ (d\circ(\pi_{(\lambda_1\times S,(i,u))})_{u\in S})_{i\in\lambda_1}
  \circ(e_u g_i)_{(i,u)\in\lambda_1\times S}
  \circ(d\circ(\pi_{(\lambda_2\times S,(j,t))})_{t\in S})_{j\in\lambda_2}/\mc\sim\right)_{s\in S}\\
=&\nu_{\lambda_1}(f)\circ (\nu_{\lambda_2}(g_i))_{i\in\lambda_1}.
\end{align*}

First, we prove $(d,(e_s)_{s\in S})$ is a diagonal pair of ${\rm H}(M)$.

1. $e_s\circ d=e_s\circ \pi_{(S,s)}$ is proved as follows:
\[
e_sd
= e_s(\pi_{(S\times S,p_2,(t,t))}^M)_{t\in S}
=e_s(\pi_{(S\times S,p_2,(s,t))}^M)_{t\in S}
= e_s\circ \pi_{(S,s)}^{{\rm H}(M)}.
\]
Here and through the proof of this proposition,
$\pi^M$ and $\pi^{{\rm H}(M)}$ denote projection constants
of $M$ and ${\rm H}(M)$ respectively.

2. $d\circ(e_s\circ\pi_{(S,s)})=d$ is proved as follows:
\begin{align*}
d(e_s\circ \pi_{(S,s)}^{{\rm H}(M)})_{s\in S}
&= (\pi_{(S\times S,p_2,(s,s))})_{s\in S}
  \circ (e_{s,t}\pi_{(S,\id,s)}^M\circ
       (\pi_{(S\times S,p_2,(s,u))})_{u\in S})_{(s,t)\in S\times S}\\
&=(e_{s,s}\pi_{(S,\id,s)}^M\circ (\pi_{(S\times S,p_2,(s,u))}^M)_{u\in S})_{s\in S} \\
&=(\pi_{(S\times S,p_2,(s,s))}^M)_{s\in S}\\
&=d.
\end{align*}

3. $d\circ(\pi_{(S,0)})_{s\in S}=\pi_{(S,0)}$ is proved as follows:
\begin{align*}
d\circ (\pi_{(S,0)}^{{\rm H}(M)})_{s\in S}
&=(\pi_{(S\times S,p_2,(s,s))}^M)_{s\in S}
  \circ (\pi_{(S\times S,p_2,(0,t))}^M)_{(s,t)\in S\times S}\\
&=(\pi_{(S\times S,p_2,(0,s))}^M)_{s\in S}\\
&=\pi_{(S,0)}^{{\rm H}(M)}.
\end{align*}
We complete the proof that $(d,(e_s)_{s\in S})$ is a diagonal pair of ${\rm H}(M)$.

(Injectivity of $\mu_{(\lambda,v,s)}$)
Let $f,g\in M_{(\lambda,v,s)}$ and assume $\mu_{(\lambda,v,s)}(f)=\mu_{(\lambda,v,s)}(g)$,
namely,
\begin{align*}
&e_{s,t}f\circ(\pi_{(\lambda\times S,p_2,(i,v(i))}^M))_{i\in\lambda}
