We give a name for a tuple of these terms.
\begin{df}\label{diagonal-pair}
Let $C$ be a single-sorted $<\mc\kappa$-ary clone.
The tuple $(d,(e_s)_{s\in S})\in C_S\times C_1{}^S$ is 
said an $S$-ary diagonal pair of $C$ if the following equations holds:
\begin{enumerate}
\item
$e_{s}\circ d=\pi_{(S,s)}$ for all $s\in S$.
\item
$d(e_s\circ \pi_{(S,s)})_{s\in S}=d$.
\item
$d(\pi_{(S,0)})_{s\in S}=\pi_{(S,0)}$ for $0\in S$.
\end{enumerate}
\end{df}

\begin{rem}
If $(d,(e_s)_{s\in S})$ is a diagonal pair of a clone $C$,
then $d$ satisfies diagonal identity
\[
d(d(\pi_{(S\times S,(s,t))})_{t\in S})_{s\in S}
=d(\pi_{(S\times S,(s,s))})_{s\in S}.
\]
Namely, $C$-algebras have diagonal algebras reduct.
\end{rem}
