\begin{align*}
\nu_\lambda(\tilde{f})
&= \left(e_s\tilde{f} \circ
 (d\circ (\pi_{(\lambda\times S,(i,u))})_{u\in S})_{i\in\lambda}/\sim\right)_{s\in S}\\
&=\left(e_s d\circ (f_{s'})_{s'\in S}
\circ(e_t\pi_{(\lambda,i)})_{(i,t)\in\lambda\times S}
\circ (d\circ (\pi_{(\lambda\times S,(i,u))})_{u\in S})_{i\in\lambda}/\mc\sim\right)_{s\in S}\\



&=\left(f_{s}
\circ (e_t\circ \pi_{(\lambda,i)})_{(i,t)\in\lambda\times S}
\circ (d\circ (\pi_{(\lambda\times S,(i,u))})_{u\in S})_{i\in\lambda}/\mc\sim\right)_{s\in S}\\
&=\left(f_{s}
\circ (e_td\circ (\pi_{(\lambda\times S,(i,u))})_{u\in S})_{(i,t)\in\lambda\times S}/\sim\right)_{s\in S}\\
&=\left(f_{s}
\circ (e_t\pi_{(\lambda\times S,(i,t))})_{(i,t)\in\lambda\times S}/\mc\sim\right)_{s\in S}\\
&=(f_{s}/\mc\sim)_{s\in S}\\
&=f.
\end{align*}

(Compatibility)
Let $f\in C_{\lambda_1}$, $g_i\in C_{\lambda_2}$ ($i\in \lambda_1$).
Then 
\begin{align*}
&\nu_{\lambda_2}(f\circ (g_i)_{i\in\lambda_1})\\
=&\left(e_s f\circ(g_i)_{i\in\lambda_1}
  \circ(d\circ(\pi_{(\lambda_2\times S,(j,t))})_{t\in S})_{j\in\lambda_2}/\mc\sim\right)_{s\in S}\\
=&\left(e_s f
  \circ (d\circ(e_u\circ \pi_{(\lambda_1,i)})_{u\in S})_{i\in\lambda_1}
  \circ(g_i)_{i\in\lambda_1}
  \circ(d\circ(\pi_{(\lambda_2\times S,(j,t))})_{t\in S})_{j\in\lambda_2}/\mc\sim\right)_{s\in S}\\
=&\left(e_s f
  \circ (d\circ(\pi_{(\lambda_1\times S,(i,u))})_{u\in S})_{i\in\lambda_1}
  \circ(e_u g_i)_{(i,u)\in\lambda_1\times S}
  \circ(d\circ(\pi_{(\lambda_2\times S,(j,t))})_{t\in S})_{j\in\lambda_2}/\mc\sim\right)_{s\in S}\\
=&\nu_{\lambda_1}(f)\circ (\nu_{\lambda_2}(g_i))_{i\in\lambda_1}.
\end{align*}
\end{proof}

By the isomorphism $\nu$ in this proposition, an ${\rm H}(C_d)$-algebra naturally has 
$C$-algebra structure.
The following isomorphism exists through this identification.

\begin{proof}
First, we prove $(d,(e_s)_{s\in S})$ is a diagonal pair of ${\rm H}(M)$.

1. $e_s\circ d=e_s\circ \pi_{(S,s)}$ is proved as follows:
\[
e_sd
= e_s(\pi_{(S\times S,p_2,(t,t))}^M)_{t\in S}
=e_s(\pi_{(S\times S,p_2,(s,t))}^M)_{t\in S}
= e_s\circ \pi_{(S,s)}^{{\rm H}(M)}.
\]
Here and through the proof of this proposition,
$\pi^M$ and $\pi^{{\rm H}(M)}$ denote projection constants
of $M$ and ${\rm H}(M)$ respectively.

2. $d\circ(e_s\circ\pi_{(S,s)})=d$ is proved as follows:
\begin{align*}
d(e_s\circ \pi_{(S,s)}^{{\rm H}(M)})_{s\in S}
&= (\pi_{(S\times S,p_2,(s,s))})_{s\in S}
  \circ (e_{s,t}\pi_{(S,\id,s)}^M\circ
       (\pi_{(S\times S,p_2,(s,u))})_{u\in S})_{(s,t)\in S\times S}\\
&=(e_{s,s}\pi_{(S,\id,s)}^M\circ (\pi_{(S\times S,p_2,(s,u))}^M)_{u\in S})_{s\in S} \\
&=(\pi_{(S\times S,p_2,(s,s))}^M)_{s\in S}\\
&=d.
\end{align*}

3. $d\circ(\pi_{(S,0)})_{s\in S}=\pi_{(S,0)}$ is proved as follows:
\begin{align*}
d\circ (\pi_{(S,0)}^{{\rm H}(M)})_{s\in S}
&=(\pi_{(S\times S,p_2,(s,s))}^M)_{s\in S}
  \circ (\pi_{(S\times S,p_2,(0,t))}^M)_{(s,t)\in S\times S}\\
&=(\pi_{(S\times S,p_2,(0,s))}^M)_{s\in S}\\
&=\pi_{(S,0)}^{{\rm H}(M)}.
\end{align*}
We complete the proof that $(d,(e_s)_{s\in S})$ is a diagonal pair of ${\rm H}(M)$.

(Injectivity of $\mu_{(\lambda,v,s)}$)
Let $f,g\in M_{(\lambda,v,s)}$ and assume $\mu_{(\lambda,v,s)}(f)=\mu_{(\lambda,v,s)}(g)$,
namely,
\begin{align*}
&e_{s,t}f\circ(\pi_{(\lambda\times S,p_2,(i,v(i))}^M))_{i\in\lambda}
 \circ (e_{v(i),u}\pi_{(\lambda\times S,p_2,(i,v(i))})_{(i,u)\in\lambda\times S}\\
=&e_{s,t}g\circ(\pi_{(\lambda\times S,p_2,(i,v(i))}^M))_{i\in\lambda}
 \circ (e_{v(i),u}\pi_{(\lambda\times S,p_2,(i,v(i))})_{(i,u)\in\lambda\times S}
\end{align*}
hold for all $t\in S$.
Notice that the following two equations hold: The first equation is
\begin{align*}
 &\pi_{(\lambda,v,v(i))}^M\\
=&e_{v(i),v(i)}\circ \pi_{(\lambda,v,v(i))}^M \\
=&\pi_{(\lambda\times S,p_2,(i,v(i)))}^M
 \circ (e_{v(j),u}\circ \pi_{(\lambda,v,v(j))}^M)_{(j,u)\in\lambda\times S}


\end{align*}
The second equation is
\[
\id_s:=\pi_{(\{s\},\id_{\{s\}},s)}^M=e_{s,s}\pi_{(S,\id_S,s)}^M (e_{s,t})_{t\in S}.
\]
By these equations injectivity of $\mu_{(\lambda,v,s)}$ is proved as follows:
\begin{align*}
f
&=\id_s\circ f\circ (\pi_{(\lambda,v,v(i))}^M)_{i\in\lambda}\\
&=e_{s,s}\pi_{(S,\id,s)}^M (e_{s,t})_{t\in S}\circ f
 (\pi_{(\lambda\times S,p_2,(i,v(i)))}^M)_{i\in\lambda}
 \circ (e_{v(j),u}\circ \pi_{(\lambda,v,v(j))}^M)_{(j,u)\in \lambda\times S}\\
&=e_{s,s}\pi_{(S,\id,s)}^M (e_{s,t})_{t\in S}\circ g
 (\pi_{(\lambda\times S,p_2,(i,v(i)))}^M)_{i\in\lambda}
 \circ (e_{v(j),u}\circ \pi_{(\lambda,v,v(j))}^M)_{(j,u)\in \lambda\times S}\\




&=g.
\end{align*}
(Surjectivity of $\mu_{(\lambda,v,s)}$)
Let $f/\mc\sim\in ({\rm H}(M))_{d,(\lambda,v,s)}$. Define $\tilde{f}$ by
$\tilde{f}=\pi_{(S,\id,s)}^M\circ f\circ
(e_{v(i),u}\circ\pi_{(\lambda,v,i)})_{(i,u)\in \lambda\times S}$.
Then the following formula holds.
\begin{align*}
\mu_{(\lambda,v,s)}(\tilde{f})
&=\left((e_{s,t})_{t\in S}\circ \tilde{f}\circ
 ( \pi_{(\lambda\times S,p_2,(i,v(i)))}^M)_{i\in\lambda}\right)/\mc\sim\\
&=\left((e_{s,t})_{t\in S}\circ \pi_{(S,\id,s)}^M\circ f\circ
 (e_{v(i),u}\circ \pi_{(\lambda,v,i)}^M)_{(i,u)\in \lambda\times S}\circ
 (\pi_{(\lambda\times S,p_2,(i,v(i)))}^M)_{i\in\lambda}\right)/\mc\sim\\
&=\left(e_s\circ f\circ
 (e_{v(i),u}\circ \pi_{(\lambda,v,i)}^M)_{(i,u)\in \lambda\times S}\circ
 (\pi_{(\lambda\times S,p_2,(i,v(i)))}^M)_{i\in\lambda}\right)/\mc\sim\\
&=\left(f\circ
 (e_{v(i),u}\circ \pi_{(\lambda\times S,p_2,(i,v(i)))}^M)_{(i,u)\in\lambda\times S}\right)/\mc\sim\\
&= f/\mc\sim.
\end{align*}
(Compatibility of $\mu$)
Let $f\in M_{(\lambda_1,v_1,s)}$ and
$g_i\in M_{(\lambda_2,v_2,v_1(i))}$ for $i\in\lambda_1$.
Then
\begin{align*}
&\mu_{(\lambda_2,v_2,s)}(f\circ (g_i)_{i\in\lambda_1})\\
=&\left((e_{s,t})_{t\in S}\circ f\circ (g_i)_{i\in\lambda_1}
 \circ (\pi_{(\lambda_2\times S,p_2,(j,v_2(j))}^M)_{j\in\lambda_2}\right)/\mc\sim\\
=&\left((e_{s,t})_{t\in S}\circ f\circ (e_{v_1(i),v_1(i)}g_i)_{i\in\lambda_1}
 \circ (\pi_{(\lambda_2\times S,p_2,(j,v_2(j))}^M)_{j\in\lambda_2}\right)/\mc\sim\\
=&\left((e_{s,t})_{t\in S}\circ f
 \circ (\pi_{(\lambda_1\times S,p_2,(i,v_1(i))}^M)_{i\in\lambda_1}
 \circ (e_{v_1(i),u})_{(i,u)\in\lambda_1\times S}\circ (g_i)_{i\in\lambda_1}
 \circ (\pi_{(\lambda_2\times S,p_2,(j,v_2(j))}^M)_{j\in\lambda_2}\right)/\mc\sim\\
=&\mu_{(\lambda_1,v_1,s)}(f)\circ (\mu_{(\lambda_2,v_2,v_1(i))}(g_i))_{i\in\lambda_1}.
\end{align*}
We complete the proof of the proposition.
\end{proof}

By this proposition, an $({\rm H}(M))_d$-algebra is identified with an
$M$-algebra. Under this identification, the following holds.

\begin{df}
Let $\kappa'$, $S_A$ and $S_B$ be cardinals, $A$ and $B$ be $S_A$-sorted, $S_B$-sorted algebra respectively.
A $<\mc\kappa'$-ary relational clone homomorphism $\Inv_{<\mc\kappa'}(A)\ra \Inv_{<\mc\kappa'}(B)$
is a family $(\ph_\mu)$ of mappings that $\ph_\mu:\Inv_\mu(A)\ra \Inv_\mu(B)$ and
preserves primitive-positive definitions, namely,
if $r_k\in \Inv_{\mu_k}(A)$ and
\[
r=\left\{(a_{s,j'})_{(s,j')\in S\times\mu}\in \left(\prod_{s\in S}A_s\right)^\mu\mid 
  \exists (a_{s,\tilde{j}})_{(s,\tilde{j})\in S\times\nu}\in\left(\prod_{s\in S}A_s\right)^\nu; 
  \bigwedge_{u\in U} (a_{s,f(u,j)})_{(s,j)\in \mu_{g(u)}}\in r_{g(u)}\right\},
\]
then
\begin{multline*}
\ph_\mu(r)=\Bigg\{(b_{s,j'})_{(s,j')\in S\times\mu}\in
 \left(\prod_{s\in S}B_s\right)^\mu\mid \\
  \exists (b_{s,\tilde{j}})_{(s,\tilde{j})\in S\times\nu}\left(\prod_{s\in S}B_s\right)^\nu; 
  \bigwedge_{u\in U} (b_{s,f(u,j)})_{(s,j)\in \mu_{g(u)}}\in \ph_{\mu_{g(u)}}(r_{g(u)})\Bigg\}.
\end{multline*}
\end{df}

